var mu sync.Mutex
var registry = map[string]*Conn{}

func ConnFor(tenant string) *Conn {
	mu.Lock()
	defer mu.Unlock()
	c, ok := registry[tenant]
	if !ok {
		c = &Conn{tenant: tenant} // created once per key
		registry[tenant] = c
	}
	return c
}

